import * as React from "react"

function BorderBottomButton({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="border-bottom-button"
      className={className}
      {...props}
    >
      <div className="flex gap-4 flex-wrap justify-center">
          <button className="px-4 py-2 border-b-4 border-green-500 text-green-500 hover hover500 transition-all duration-200">Button 1</button>
          <button className="px-4 py-2 border-b-4 border border-red-500 text-red-500 hover hover500 transition-all duration-200">Button 2</button>
          <button className="bg-blue-500 hover700 text-white font-bold py-2 px-4 border-b-4 border-blue-700 rounded transform transition duration-200 ease-in-out hover1 hover110">Button 3</button>
      </div>
    </div>
  )
}

export { BorderBottomButton }
